mapper.select:
SELECT game_id, user_id, nickname, matches, wins, losses, points, championships,
       visible, display_order, managed_by, managed_at, updated_at
  FROM game_player_game_stat
 WHERE game_id = #{gameId}
 ORDER BY display_order DESC, points DESC, championships DESC, wins DESC, updated_at ASC
 LIMIT #{limit}

SELECT position FROM (
  SELECT user_id,
         ROW_NUMBER() OVER (
             ORDER BY display_order DESC, points DESC, championships DESC,
                      runner_ups DESC, updated_at ASC
         ) AS position
    FROM game_player_stat
   WHERE visible = 1
) ranked
WHERE user_id = #{userId}

mapper.update:
UPDATE game_player_stat
   SET best_score = GREATEST(best_score, #{score}), nickname = #{nickname},
       updated_at = #{now}
 WHERE user_id = #{userId}

UPDATE game_player_stat
matches = #{matches}, wins = #{wins}, losses = #{losses}, points = #{points}, championships = #{championships}, runner_ups = #{runnerUps}, best_score = #{bestScore}, visible = #{visible}, display_order = #{displayOrder}, managed_by = #{managedBy}, managed_at = #{now}, updated_at = #{now}
WHERE user_id = #{userId}

UPDATE game_player_game_stat
matches = #{matches}, wins = #{wins}, losses = #{losses}, points = #{points}, championships = #{championships}, visible = #{visible}, display_order = #{displayOrder}, managed_by = #{managedBy}, managed_at = #{now}, updated_at = #{now}
WHERE game_id = #{gameId} AND user_id = #{userId}
